def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r][c] or grid[r][c] == bg:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] != bg):
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            components.append(cells)

    frame = max(components, key=len)
    fc = grid[frame[0][0]][frame[0][1]]
    fcells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fc]
    top, bottom = min(r for r, c in fcells), max(r for r, c in fcells)
    left, right = min(c for r, c in fcells), max(c for r, c in fcells)
    oh, ow = bottom - top + 1, right - left + 1

    hole_mask = 0
    for y in range(oh):
        for x in range(ow):
            if grid[top + y][left + x] == bg:
                hole_mask |= 1 << (y * ow + x)

    objects = []
    for comp in components:
        if grid[comp[0][0]][comp[0][1]] == fc:
            continue
        r0, c0 = min(r for r, c in comp), min(c for r, c in comp)
        shape = [(r - r0, c - c0, grid[r][c]) for r, c in comp]
        bh = max(r for r, c, v in shape) + 1
        bw = max(c for r, c, v in shape) + 1
        placements = []
        for y in range(oh - bh + 1):
            for x in range(ow - bw + 1):
                mask = 0
                valid = True
                for dy, dx, value in shape:
                    bit = 1 << ((y + dy) * ow + x + dx)
                    if not (hole_mask & bit):
                        valid = False
                        break
                    mask |= bit
                if valid:
                    placements.append((mask, y, x))
        objects.append((shape, placements))

    answer = None

    def search(remaining, used, placed):
        nonlocal answer
        if answer is not None:
            return
        if not remaining:
            if used == hole_mask:
                answer = placed[:]
            return
        best_i = -1
        best_options = None
        for i in remaining:
            options = [p for p in objects[i][1] if not (p[0] & used)]
            if not options:
                return
            if best_options is None or len(options) < len(best_options):
                best_i, best_options = i, options
                if len(options) == 1:
                    break
        rest = [i for i in remaining if i != best_i]
        for mask, y, x in best_options:
            placed.append((best_i, y, x))
            search(rest, used | mask, placed)
            placed.pop()
            if answer is not None:
                return

    search(list(range(len(objects))), 0, [])
    out = [[fc] * ow for _ in range(oh)]
    if answer is not None:
        for i, y, x in answer:
            for dy, dx, value in objects[i][0]:
                out[y + dy][x + dx] = value
    return out
